function validate([statements]) {
  if (!Array.isArray(statements)) return 'statements must be a matrix.';
  const n = statements.length;
  if (n < 2 || n > 15) return 'There are 2 to 15 people.';
  for (let i = 0; i < n; i++) {
    if (!Array.isArray(statements[i]) || statements[i].length !== n) return 'statements must be square.';
    if (statements[i].some(v => v !== 0 && v !== 1 && v !== 2)) return 'Each entry is 0, 1 or 2.';
    if (statements[i][i] !== 2) return 'Nobody makes a statement about themselves (statements[i][i] = 2).';
  }
  return null;
}

