function maximumGood(statements) {
  const n = statements.length;
  let best = 0;

  for (let mask = 1; mask < 1 << n; mask++) {
    let good = 0;
    let valid = true;
    for (let i = 0; i < n && valid; i++) {
      if (((mask >> i) & 1) === 0) {
        continue;
      }
      good++;
      for (let j = 0; j < n; j++) {
        const claim = statements[i][j];
        if (claim !== 2 && claim !== ((mask >> j) & 1)) {
          valid = false;
          break;
        }
      }
    }
    if (valid) {
      best = Math.max(best, good);
    }
  }
  return best;
}

