function maximumGood(statements) {
  const n = statements.length;
  const roles = [];
  let best = 0;
  const consistent = () => {
    for (let i = 0; i < n; i++) {
      if (!roles[i]) continue;
      for (let j = 0; j < n; j++) {
        if (statements[i][j] === 1 && !roles[j]) return false;
        if (statements[i][j] === 0 && roles[j]) return false;
      }
    }
    return true;
  };
  const assign = (person) => {
    if (person === n) {
      if (consistent()) best = Math.max(best, roles.filter(Boolean).length);
      return;
    }
    roles[person] = true;
    assign(person + 1);
    roles[person] = false;
    assign(person + 1);
  };
  assign(0);
  return best;
}

