function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(13, 15) : int(2, 7);
  const truth = Array.from({ length: n }, () => rand() < 0.6);
  const planted = rand() < 0.6;
  const silence = rand() * 0.7;
  const statements = [];
  for (let i = 0; i < n; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      if (i === j || rand() < silence) row.push(2);
      else if (planted && truth[i]) row.push(truth[j] ? 1 : 0);
      else row.push(int(0, 1));
    }
    statements.push(row);
  }
  return [statements];
}
